from machine import I2C,UART,Pinfrom  Sengo1  import *import time# 等待Sengo1完成操作系统的初始化。此等待时间不可去掉，避免出现Sengo1尚未初始化完毕主控器已经开发发送指令的情况time.sleep(2)# 选择UART或者I2C通讯模式，Sengo1出厂默认为I2C模式，短按模式按键可以切换# 4种UART通讯模式：UART9600（标准协议指令），UART57600（标准协议指令），UART115200（标准协议指令），Simple9600（简单协议指令），# 参看“简单协议指令”# https://tosee.readthedocs.io/zh/latest/Common/Protocol/index.html#section-6########################################################################################################## port = UART(2,rx=Pin(16),tx=Pin(17),baudrate=9600)port = I2C(1,scl=Pin(22),sda=Pin(21),freq=400000)# Sengo1通讯地址：0x60。如果I2C总线挂接多个设备，请避免出现地址冲突sengo1 = Sengo1(0x60)err = sengo1.begin(port)if err != SENTRY_OK:    print(f"Initialization failed，error code:{err}")else:    print("Initialization succeeded")# 1、参考文档# https://tosee.readthedocs.io/zh/latest/Sentry1/Vision/index.html#chapter-vs1-vision-ball-index# 2、参考视频（注：Sengo1与Sentry1是两款产品）# https://www.bilibili.com/video/BV1FX4y1Z7Jx/?spm_id_from=333.1387.upload.video_card.click&vd_source=a6a4a13d17ed26ee248472534a8ec3cc# 3、球体检测算法的常见应用：踢球或者抓球小车# 4、Sengo1每次只能运行一种识别算法；# 5、正常使用时，应由主控板通过指令控制Sengo1算法的开启与关闭，而不是通过Sengo1的按键进行操作；err = sengo1.VisionBegin(sengo1_vision_e.kVisionBody)if err != SENTRY_OK:    print(f"Starting algo Body failed，error code:{err}")else:    print("Starting algo Body succeeded")while True:    # Sengo1不主动返回检测识别结果，需要主控板发送指令进行读取。读取的流程：首先读取识别结果的数量，接收到指令后，Sengo1会刷新结果数据，如果结果数量不为零，那么主控再发送指令读取结果的相关信息。请务必按此流程构建程序。    obj_num = sengo1.GetValue(sengo1_vision_e.kVisionBody, sentry_obj_info_e.kStatus)    if obj_num:        x = sengo1.GetValue(sengo1_vision_e.kVisionBody, sentry_obj_info_e.kXValue)        y = sengo1.GetValue(sengo1_vision_e.kVisionBody, sentry_obj_info_e.kYValue)        w = sengo1.GetValue(sengo1_vision_e.kVisionBody, sentry_obj_info_e.kWidthValue)        h = sengo1.GetValue(sengo1_vision_e.kVisionBody, sentry_obj_info_e.kHeightValue)        print("body: x=%d, y=%d, w=%d, h=%d"%(x, y, w, h))        time.sleep(0.2)        print("\n")    